/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
/// Creating multi tread batch tasks
/// </summary>

class METPOConfirmationPostMultiThreadBatch extends RunbaseBatch
{
    // Packed variables
    BatchHeader batchHeader;
    container   companyAndPurchId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        companyAndPurchId
    #endmacro
   
}

Method.Source:
        /// <summary>
        /// Contains the code that does the actual job of the class.
        /// </summary>
        public void run()
        {
            #OCCRetryCount
            #Characters
            int counter;
            METPOConfirmationPostMultiThreadTask metPOConfirmationPostMultiThreadTask;
            for(counter=1;counter<=conLen(companyAndPurchId);counter++)
            {
                container companyAndPurchIdSingle           = conPeek(companyAndPurchId,counter);

                if(!batchHeader)
                {
                    batchHeader = BatchHeader::construct(this.parmCurrentBatch().BatchJobId);
                }
                batchHeader.parmCaption("@MET:PurchaseOrderConfirmationMultiTreadBatchJob");
                metPOConfirmationPostMultiThreadTask = new METPOConfirmationPostMultiThreadTask();
                metPOConfirmationPostMultiThreadTask.parmCompanyAndPurchId(companyAndPurchIdSingle);
                // add tasks to the batch header
                batchHeader.addRuntimeTask(metPOConfirmationPostMultiThreadTask, this.parmCurrentBatch().RecId);
            
            }
            if(batchHeader)
            {
                // save the batchheader with added tasks
                batchHeader.save();
            }
        }

        public boolean unpack(container packedClass)
        {
            Version version = RunBase::getVersion(packedClass);
            ;
            switch (version)
            {
                case #CurrentVersion:
                    [version,#CurrentList] = packedClass;
                    break;
                default:
                    return false;
            }

            return true;
        }

/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
/// </summary>
/// <param name="_companyAndPurchIds"> Get container</param>
public void parmCompanyAndPurchIds(container _companyAndPurchIds)
{
    companyAndPurchId = _companyAndPurchIds;
}

static METPOConfirmationPostMultiThreadBatch construct()
{
    return new METPOConfirmationPostMultiThreadBatch();
}

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
    /// <returns>
    /// A ClassDescription
    /// </returns>
    /// Here goes a description of the class
    /// </summary>

    static ClassDescription description()
    {
        return "@MET:PurchaseOrderConfirmationMultiTreadBatchJob";
    }

        static void main(Args args)
        {
            METPOConfirmationPostMultiThreadBatch    metPOConfirmationPostMultiTreadBatch;
    
            metPOConfirmationPostMultiTreadBatch = METPOConfirmationPostMultiThreadBatch::construct();

            if (metPOConfirmationPostMultiTreadBatch.prompt())
            {                
                metPOConfirmationPostMultiTreadBatch.runOperation();
            }
        }
